103.4 Inference rule
structure AssuranceRule where
  Premise : Type
  premiseClaim :
    Premise → Claim

  conclusion : Claim

  sound :
    ∀ ω,
      (∀ p : Premise,
        Holds ω (premiseClaim p)) →
      Holds ω conclusion



103.5 Assurance derivation
inductive Derivation : Claim → Type
| leafEvidence :
    (e : EvidenceAtom) →
    EvidenceUsable e →
    Derivation e.directClaim

| leafAssumption :
    (a : AssuranceAssumption) →
    AssumptionDischarged a →
    Derivation a.proposition

| infer :
    (r : AssuranceRule) →
    (ds :
      ∀ p : r.Premise,
        Derivation (r.premiseClaim p)) →
    Derivation r.conclusion
This intrinsic form excludes ungrounded cycles.
Shared DAGs may be represented separately and checked against the inductive semantics.



103.6 Derivation soundness
theorem derivation_sound
    (D : Derivation C)
    (hApplicable :
      AllEvidenceApplicable D Gamma)
    (hVersions :
      VersionsMatch D) :
    ∀ ω ∈ Gamma,
      Holds ω C := by
  induction D with
  | leafEvidence e hUsable =>
      exact evidence_leaf_sound ...
  | leafAssumption a hDischarged =>
      exact assumption_leaf_sound ...
  | infer r ds ih =>
      intro ω hω
      apply r.sound
      intro p
      exact ih p ω hω



103.7 Support and cores
def Supports
    (S : Finset ExternalLeafId)
    (C : Claim) : Prop :=
  ∃ D : Derivation C,
    leafIds D ⊆ S
def IsMinimalCore
    (S : Finset ExternalLeafId)
    (C : Claim) : Prop :=
  Supports S C ∧
  ∀ S' ⊂ S,
    ¬ Supports S' C



103.8 Evidence cuts
def IsEvidenceCut
    (H : Finset ExternalLeafId)
    (C : Claim) : Prop :=
  ∀ D : ValidDerivation C,
    (leafIds D ∩ H).Nonempty



103.9 Assurance consistency
def AssuranceConsistent
    (A : AssuranceCase) : Prop :=
  ∃ ω,
    SatisfiesFoundations ω A



103.10 Release closure
def ReleaseClosed
    (A : AssuranceCase)
    (manifest : Finset Claim) : Prop :=
  AssuranceConsistent A ∧
  ∀ C ∈ manifest,
    ∃ D,
      ValidDerivationIn A D C



103.11 Incremental invalidation
def invalidationClosure
    (changed : Finset Node)
    (G : DependencyGraph) :
    Finset Node :=
  changed ∪ descendants G changed



