Activity
structure Activity where
  id : ActivityId
  duration : Nat
  demand : Resource → Nat
Precedence feasibility
def PrecedenceFeasible
    (pred : Activity → Activity → Prop)
    (start : Activity → Nat) : Prop :=
  ∀ a b,
    pred a b →
    start b ≥ start a + a.duration
Renewable-resource feasibility
A discrete-time formalization:
def ResourceFeasible
    (activities : Finset Activity)
    (start : Activity → Nat)
    (capacity : Resource → Nat → Nat) : Prop :=
  ∀ r t,
    ∑ a in activities.filter
      (fun a =>
        start a ≤ t ∧
        t < start a + a.duration),
      a.demand r
    ≤
    capacity r t
Inventory
structure InventoryState where
  amount : Material → ℝ

def inventoryStep
    (I : InventoryState)
    (delivery use loss : Material → ℝ) :
    InventoryState :=
  {
    amount :=
      fun m =>
        I.amount m
        + delivery m
        - use m
        - loss m
  }
Cash
structure CashState where
  balance : ℝ

def cashStep
    (B : CashState)
    (receipt outflow : ℝ) :
    CashState :=
  {
    balance :=
      B.balance + receipt - outflow
  }
Execution witness
structure ExecutionWitness where
  schedule : Schedule
  resources : ResourcePlan
  procurement : ProcurementPlan
  inventory : InventoryTrace
  logistics : LogisticsPlan
  cash : CashTrace
  carbon : CarbonTrace
  mode : EcoMode
Execution fiber
def ExecutionFiber
    (b : ConcreteArtifact)
    (mode : EcoMode) :
