56. Proof-Assistant Formalization
Commitment decision node
structure DecisionNode where
  time : Time
  State : Type
  state : State
  History : Type
  history : History
  theoryVersion : Hash
Nonanticipative policy on an information tree
structure InfoNode where
  stage : Nat
  observations : List Observation

structure Policy where
  choose : InfoNode → Action
  admissible :
    ∀ h,
      ActionAdmissible h (choose h)
Policies are defined on information nodes rather than hidden scenario leaves, making nonanticipativity structural.
Continuation fiber
def ContinuationFiber
    (n : DecisionNode) :
    Set Policy :=
  {π |
    AdmissibleFrom n π}
Action-conditioned continuation fiber
def ConditionedFiber
    (n : DecisionNode)
    (a : Action) :
    Set Policy :=
  {π |
    π ∈ ContinuationFiber n ∧
    FirstAction π n = a}
Subset theorem
theorem conditioned_subset
    (n : DecisionNode)
    (a : Action) :
    ConditionedFiber n a
      ⊆
    ContinuationFiber n := by
  intro π h
  exact h.1
Contextual reversibility
def ContextuallyReversible
    (x : State)
    (a : Action)
    (T : ExperimentTheory) : Prop :=
  ∃ w : ActionWord,
    ContextuallyEquivalent T
      (ExecuteWord w (Execute a x))
      x
Engineering option
structure EngineeringOption where
  exercise : Action
  window : TimeWindow
  precondition : State → Prop
  authority : AuthorityRequirement
  version : Version
Live option
def LiveOption
    (n : DecisionNode)
    (o : EngineeringOption) : Prop :=
  InWindow n.time o.window ∧
  RightsValid n o ∧
  ∃ π,
    OptionExercisePolicy n o π ∧
    Nonanticipative π
Commitment preorder
def MoreCommitted
    (n₁ n₂ : DecisionNode) : Prop :=
  OutcomeImage n₁ ⊆ OutcomeImage n₂
Viability recursion
def viability
    : Nat → Set State
| 0 =>
    terminalAcceptable
| t + 1 =>
    {s |
      ∃ a ∈ allowed s,
        ∀ w ∈ disturbance s a,
          ∀ s',
            step s a w s' →
            s' ∈ viability t}
Robust Bellman skeleton
def robustValue
    : Nat → State → ℝ
| 0, s =>
    terminalReward s
| t + 1, s =>
    Finset.max'
      ((actions s).image
        (fun a =>
          Finset.min'
            ((kernelSet s a).image
              (fun p =>
                expected p
                  (fun s' =>
                    reward s a s'
                    + robustValue t s')))))
      ...
A formal development would require nonempty finite action and kernel sets.
PCCP
structure PCCP where
  project : ProjectId
  currentNode : DecisionNode
  actionTheory : ActionTheory
  commitments : CommitmentLedger
  options : OptionStore
  information : InformationModel
  policy : PolicyCertificate
  viability : ViabilityCertificate
  dependencies : DependencyGraph
  version : Version



